  const tagKey=name=>name.normalize('NFKC').replace(/^[#＃]+/,'').trim().toLowerCase();
  const canonical=(name,labels)=>labels.find(t=>[t.name,...(t.aliases||[])].some(a=>tagKey(a)===tagKey(name)))?.name||name.normalize('NFKC').replace(/^[#＃]+/,'').trim();
  function hashtagMask(text){return text.replace(/```[\s\S]*?(?:```|$)|~~~[\s\S]*?(?:~~~|$)/g,s=>s.replace(/[^\n]/g,' ')).replace(/`[^`\n]*`/g,s=>' '.repeat(s.length));}
  function hashtags(text){const result=[];const mask=hashtagMask(text);const pattern=/(^|\s)[#＃]([\p{L}\p{N}_][\p{L}\p{N}_/-]{0,63})(?![\p{L}\p{N}_/-])/gu;let m;while((m=pattern.exec(mask)))result.push({name:m[2],start:m.index+m[1].length,end:pattern.lastIndex});return result;}
  function selectedTags(content,chosen,labels){const names=[...chosen,...hashtags(content).map(t=>t.name)].map(t=>canonical(t,labels));return names.filter((name,i)=>names.findIndex(x=>tagKey(x)===tagKey(name))===i);}
  function readLanguage(){try{return localStorage.getItem('slipbox.plugin.language')==='en'?'en':'zh';}catch{return 'zh';}}
  async function api(input, signal) {
    const response = await fetch('api/slipbox/cards', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(input), signal });
    const data = await response.json();
    if (!response.ok || !data.ok) throw new Error(data.error || copy.loadError[readLanguage()==='en'?1:0]);
    return data.value;
  }
